@font-face{font-family:"Noto Sans KR";src:url("assets/fonts/NotoSansKR.ttf") format("truetype");font-weight:100 900;font-style:normal;font-display:swap;}
*{box-sizing:border-box}body{margin:0;color:#202024;background:#f3f3f5;font-family:"Noto Sans KR",sans-serif;font-weight:500}button,input,select{font:inherit}button{cursor:pointer}img{display:block;max-width:100%}p,h1,h2,h3{margin:0}button:focus-visible,a:focus-visible{outline:3px solid #5146d7;outline-offset:4px}.product{max-width:1120px;margin:40px auto;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:32px;padding:0 24px;align-items:start}.details{min-width:0}.media-navigation{position:relative;min-width:0}.detail-navigation{position:absolute;z-index:1;left:16px;top:16px}#back{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:50%;background:rgb(255 255 255 / .94);box-shadow:0 2px 12px rgb(0 0 0 / .08)}.product-identity{background:white;padding:28px}#booking-layout{padding-top:12px}.booking-host,.booking-surface{background:#fff;padding:24px 28px}.booking-surface{margin-top:12px}#booking-actions{display:grid;grid-template-columns:48px minmax(0,1fr);align-items:center;gap:12px}.section-label{font-size:14px;font-weight:500;line-height:1.6;color:#60606a;margin-bottom:8px}@media(max-width:700px){.product{display:block;margin:0;padding:0}.details{padding:0}.product-identity{padding:24px 20px}.booking-host,.booking-surface{padding:24px 20px}}
[data-ui-unit="media"].product-media {
  width: 100%;
  aspect-ratio: 1 / 1;
  margin: 0;
  overflow: hidden;
}

[data-ui-unit="media"].product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 44% center;
}

@media (min-width: 701px) {
  [data-ui-unit="media"].product-media {
    border-radius: 8px;
  }
}
[data-ui-unit="identity"].product-identity .eyebrow {
  font-size: 14px;
  font-weight: 500;
  color: #60606a;
  margin-bottom: 8px;
}

[data-ui-unit="identity"].product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: #202024;
  word-break: keep-all;
  overflow-wrap: break-word;
}

[data-ui-unit="identity"].product-identity .price-row {
  margin-top: 12px;
}

[data-ui-unit="identity"].product-identity .price {
  font-size: 24px;
  font-weight: 800;
  color: #202024;
}

[data-ui-unit="identity"].product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 24px;
}

[data-ui-unit="identity"].product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

[data-ui-unit="identity"].product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
  object-fit: contain;
  color: #60606a;
}

[data-ui-unit="identity"].product-identity .meta-item span {
  font-size: 14px;
  font-weight: 500;
  color: #60606a;
  white-space: nowrap;
}

[data-ui-unit="identity"].product-identity .description {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.75;
  color: #202024;
  margin-top: 20px;
}
[data-ui-unit="booking"] .booking-host-title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.4;
  color: #202024;
}

[data-ui-unit="booking"] .booking-host-subtitle {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: #60606a;
  margin-top: 4px;
}

[data-ui-unit="booking"] .booking-icon-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f2f2f5;
  border-radius: 8px;
  border: none;
  padding: 0;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

[data-ui-unit="booking"] .booking-icon-btn img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  pointer-events: none;
}

[data-ui-unit="booking"] .booking-icon-btn:hover {
  background-color: #e8e8ed;
}

[data-ui-unit="booking"] .booking-icon-btn:active {
  transform: scale(0.96);
}

[data-ui-unit="booking"] .booking-icon-btn[aria-pressed="true"] {
  background-color: #eef0fc;
}

[data-ui-unit="booking"] .booking-primary-btn {
  min-height: 52px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  border-radius: 6px;
  border: none;
  white-space: normal;
  overflow-wrap: break-word;
  word-break: keep-all;
  text-align: center;
  min-width: 0;
}

[data-ui-unit="booking"] .booking-note {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: #60606a;
  margin-top: 12px;
}
dialog{width:min(480px,calc(100% - 32px));max-height:calc(100dvh - 32px);padding:28px;border:0;border-radius:12px;color:#202024}dialog::backdrop{background:rgb(20 20 24 / .45)}.dialog-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.dialog-heading h2{font-size:22px}.dialog-heading button{border:0;background:#f1f1f5;padding:10px;font-size:14px;font-weight:600;border-radius:4px}.booking-class{font-weight:700;font-size:18px;line-height:1.5}.booking-price{margin:8px 0 24px;font-size:15px;color:#555560}#booking-form label{display:block;margin:16px 0 8px;font-size:15px;font-weight:600}#booking-form input,#booking-form select{display:block;width:100%;min-width:0;min-height:48px;border:1px solid #bcbcc6;border-radius:6px;padding:10px 12px;background:#fff;color:#202024;font-size:16px;font-weight:500}.confirm-booking{width:100%;min-height:52px;margin-top:24px;border:0;border-radius:6px;background:#5146d7;color:#fff;font-weight:700}.confirm-booking:hover{background:#4036b8}#storage-error{font-size:14px;line-height:1.5;color:#a52c26}#confirmation h3{font-size:20px;margin-top:24px}#confirmation-details{white-space:pre-line;line-height:1.9;font-size:16px;margin:16px 0}#cancel-booking{padding:12px 16px;border:1px solid #bcbcc6;border-radius:6px;background:white;color:#202024;font-weight:600}@media(max-width:360px){dialog{padding:20px}}

