.class-list{max-width:720px;margin:48px auto;padding:0 20px}.class-list h1{font-size:28px;line-height:1.5;margin-bottom:24px}.class-link{display:block;color:inherit;text-decoration:none;background:#fff;border-radius:12px;overflow:hidden}.class-link img{width:100%;aspect-ratio:16/10;object-fit:cover}.class-copy{padding:24px}.class-copy h2{font-size:20px;line-height:1.5;margin:8px 0 16px}.class-copy p{line-height:1.7}

